import{_ as t,o as a,c as d,a2 as r}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"26 - Traffic Logs","description":"","frontmatter":{},"headers":[],"relativePath":"developers/design-documentation/26-traffic-logs.md","filePath":"developers/design-documentation/26-traffic-logs.md"}'),o={name:"developers/design-documentation/26-traffic-logs.md"};function s(i,e,c,n,l,h){return a(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="_26-traffic-logs" tabindex="-1">26 - Traffic Logs <a class="header-anchor" href="#_26-traffic-logs" aria-label="Permalink to &quot;26 - Traffic Logs&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Tradeboard records HTTP request metadata for monitoring, latency review, and security analysis. It does not store request bodies, response bodies, headers, user agents, or a per-request processing timeline in the traffic table.</p><h2 id="capture-flow" tabindex="-1">Capture Flow <a class="header-anchor" href="#capture-flow" aria-label="Permalink to &quot;Capture Flow&quot;">​</a></h2><p><code>utils/traffic_logger.py</code> wraps the Flask WSGI application. For each included request it captures context before submitting a serialized write to a single-worker executor:</p><table tabindex="0"><thead><tr><th>Field</th><th>Source</th></tr></thead><tbody><tr><td><code>timestamp</code></td><td>Database default</td></tr><tr><td><code>client_ip</code></td><td>Trusted client-IP helper</td></tr><tr><td><code>method</code></td><td>Flask request method</td></tr><tr><td><code>path</code></td><td>Flask request path</td></tr><tr><td><code>status_code</code></td><td>WSGI response status</td></tr><tr><td><code>duration_ms</code></td><td>Middleware wall time</td></tr><tr><td><code>host</code></td><td>Request host</td></tr><tr><td><code>error</code></td><td>Unhandled middleware exception, when present</td></tr><tr><td><code>user_id</code></td><td><code>flask.g</code>, when populated</td></tr></tbody></table><p>Writes go to <code>logs.db</code> through <code>database/traffic_db.py</code>. The executor has one worker so SQLite commits remain serialized and do not delay the HTTP response. The worker removes its scoped session after every write.</p><p>Static assets, the favicon, latency-log reads, and the traffic dashboard&#39;s own routes are excluded to avoid noise and recursion.</p><h2 id="dashboard" tabindex="-1">Dashboard <a class="header-anchor" href="#dashboard" aria-label="Permalink to &quot;Dashboard&quot;">​</a></h2><p>The supported React page is <code>/logs/traffic</code>. <code>traffic_bp</code> is registered with <code>url_prefix=&quot;/traffic&quot;</code>, and <code>GET /traffic/</code> still renders the older server-side template. The React page calls the session-authenticated routes under <code>/traffic</code>:</p><table tabindex="0"><thead><tr><th>Route</th><th>Behavior</th></tr></thead><tbody><tr><td><code>GET /traffic/api/logs</code></td><td>Return recent entries; <code>limit</code> defaults to 100 and is capped at 1,000</td></tr><tr><td><code>GET /traffic/api/stats</code></td><td>Return overall, <code>/api/v1</code>-only, and selected endpoint statistics</td></tr><tr><td><code>GET /traffic/export</code></td><td>Export the current log set as CSV</td></tr></tbody></table><p>The page shows total requests, error requests, average duration, a recent-request table, and per-endpoint totals/errors/average duration. UI filters select all versus <code>/api/v1</code> traffic and all, successful, or error status.</p><p>The table displays timestamp, method, path, status, duration, client IP, and host. It deliberately does not expose stored request/response payloads because none are collected.</p><h2 id="retention" tabindex="-1">Retention <a class="header-anchor" href="#retention" aria-label="Permalink to &quot;Retention&quot;">​</a></h2><p><code>init_traffic_logging()</code> initializes the store, purges rows beyond the retention window, and then installs the middleware. <code>purge_old_traffic_logs()</code> deletes <code>traffic_logs</code> rows older than <code>TRAFFIC_LOG_RETENTION_DAYS</code> (env var, default <code>30</code>) and runs once at startup. Retention is not driven by the persisted security settings, and there is no multi-tier archive scheme.</p><h2 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to &quot;Security&quot;">​</a></h2><ul><li>Proxy-derived IP headers are trusted only when <code>TRUST_PROXY_HEADERS</code> is enabled for a controlled reverse proxy.</li><li>API keys and tokens are not captured because traffic logging stores metadata only.</li><li>Dashboard, stats, logs, and export routes require a valid application session and have explicit rate limits.</li><li><code>logs.db</code> also contains IP-ban and invalid-attempt security data; it is separate from <code>tradeboard.db</code>. Its location comes from <code>LOGS_DATABASE_URL</code> (default <code>sqlite:///db/logs.db</code>).</li></ul><h2 id="key-files" tabindex="-1">Key Files <a class="header-anchor" href="#key-files" aria-label="Permalink to &quot;Key Files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Responsibility</th></tr></thead><tbody><tr><td><code>utils/traffic_logger.py</code></td><td>Middleware, exclusions, asynchronous write dispatch</td></tr><tr><td><code>database/traffic_db.py</code></td><td>Traffic schema, queries, retention, IP/security tables</td></tr><tr><td><code>blueprints/traffic.py</code></td><td>Logs, stats, CSV export, legacy template route</td></tr><tr><td><code>frontend/src/pages/monitoring/TrafficDashboard.tsx</code></td><td>Current dashboard</td></tr></tbody></table>',19)])])}const f=t(o,[["render",s]]);export{p as __pageData,f as default};
